      var cc = ['#b4532a', '#d9782f', '#eda046', '#8e3b22'];
      for (var b = 0; b < 9; b++) oval(g, x + tw / 2 + (R() - 0.5) * 70, R() * 26, 14 + R() * 10, 8 + R() * 6, cc[b % 4]);
      for (var d = 0; d < 26; d++) rect(g, x + tw / 2 + (R() - 0.5) * 80, R() * 40, 2, 2, cc[(d + 2) % 4]);
      // chestnut burrs hanging
