        if (tileAt(c, r) !== DIRT || tileAt(c, r - 1) !== EMPTY) continue;
        x = c * T; y = r * T;
        for (i = 0; i < 16; i++) if (R() < 0.35) rect(g, x + i, y - 1 - Math.floor(R() * 3), 1, 3, R() < 0.5 ? '#b8a640' : '#8f8a2e');
        if (R() < 0.5) rect(g, x + Math.floor(R() * 13), y, 3, 1, LEAF_COLS[Math.floor(R() * 4)]);
